input.command:
mkdir -p src && cat > package.json <<'EOF'
{
  "name": "fireworks-3d-vfx-2",
  "private": true,
  "version": "2.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "0.180.0"
  },
  "devDependencies": {
    "vite": "8.3.5"
  }
}
EOF
npm install

input.content:
:root {
  --ink: #f7f4ec;
  --muted: rgba(234, 238, 247, 0.54);
  --dim: rgba(234, 238, 247, 0.32);
  --panel: rgba(8, 11, 19, 0.74);
  --panel-solid: #090c14;
  --line: rgba(255, 255, 255, 0.11);
  --line-soft: rgba(255, 255, 255, 0.065);
  --gold: #ffd08a;
  --gold-deep: #ffad53;
  --rose: #ff6f9c;
  --cyan: #7ef9ff;
  --accent: #ffd08a;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --display: "Bebas Neue", "Arial Narrow", "Futura Condensed", sans-serif;
  --ui: "Manrope", "Avenir Next", "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #03050a;
  color: var(--ink);
  font-family: var(--ui);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  user-select: none;
}

button,
input,
label {
  font: inherit;
  color: inherit;
}

button {
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: 0;
  touch-action: none;
}

#ui {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
}

#ui button,
#ui input,
#ui label {
  pointer-events: auto;
}

#loader {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background:
    radial-gradient(circle at 50% 44%, rgba(36, 30, 55, 0.8), transparent 38%),
    radial-gradient(circle at 50% 120%, rgba(30, 13, 20, 0.7), transparent 45%),
    #03050a;
  transition: opacity 1s cubic-bezier(0.22, 1, 0.36, 1), visibility 1s;
}

#loader.is-done {
  opacity: 0;
  visibility: hidden;
}

.loader-mark {
  position: relative;
  width: 56px;
  height: 56px;
  animation: spin 16s linear infinite;
}

.loader-mark i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2px;
  height: 15px;
  margin-left: -1px;
  background: linear-gradient(to top, transparent, var(--gold));
  transform-origin: 50% 0;
  opacity: 0.85;
  border-radius: 999px;
}

.loader-mark i:nth-child(1) { transform: translateY(10px) rotate(0deg); }
.loader-mark i:nth-child(2) { transform: translateY(10px) rotate(60deg); }
.loader-mark i:nth-child(3) { transform: translateY(10px) rotate(120deg); }
.loader-mark i:nth-child(4) { transform: translateY(10px) rotate(180deg); }
.loader-mark i:nth-child(5) { transform: translateY(10px) rotate(240deg); }
.loader-mark i:nth-child(6) { transform: translateY(10px) rotate(300deg); }

.loader-mark::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 7px;
  height: 7px;
  margin: -3.5px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 18px 5px rgba(255, 208, 138, 0.9);
}

.loader-title {
  font-family: var(--display);
  font-size: 34px;
  letter-spacing: 0.18em;
  line-height: 1;
}

.loader-title b {
  color: var(--gold);
  font-weight: inherit;
}

.loader-sub {
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.26em;
  font-weight: 600;
}

.loader-track {
  width: 148px;
  height: 1px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.14);
  margin-top: 6px;
}

.loader-track span {
  display: block;
  width: 45%;
  height: 100%;
  background: linear-gradient(90deg, transparent, #fff, var(--gold));
  animation: load-sweep 1.1s ease-in-out infinite;
}

@keyframes load-sweep {
  0% { transform: translateX(-110%); }
  100% { transform: translateX(340%); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ------------------------------- top chrome ------------------------------- */
.topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: calc(22px + var(--safe-top)) calc(28px + var(--safe-right)) 0 calc(30px + var(--safe-left));
  z-index: 3;
  pointer-events: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  pointer-events: auto;
}

.brand-mark {
  width: 38px;
  height: 38px;
  border: 1px solid rgba(255, 255, 255, 0.17);
  background: rgba(5, 8, 14, 0.42);
  backdrop-filter: blur(12px);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 18px rgba(255, 208, 138, 0.06);
}

.brand-mark svg {
  width: 23px;
  height: 23px;
  fill: none;
  stroke: var(--gold);
  stroke-width: 1.2;
  filter: drop-shadow(0 0 5px rgba(255, 190, 114, 0.65));
}

.brand-name {
  font-family: var(--display);
  font-size: 21px;
  letter-spacing: 0.12em;
  line-height: 1;
}

.brand-name b {
  font-weight: inherit;
  color: var(--gold);
}

.brand-tag {
  margin-top: 5px;
  color: var(--dim);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

.brand-tag span {
  color: rgba(255, 208, 138, 0.84);
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
}

.auto-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(6, 9, 16, 0.47);
  backdrop-filter: blur(12px);
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.15em;
  transition: 0.25s ease;
}

.auto-toggle .auto-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--dim);
  transition: 0.25s ease;
}

.auto-toggle.is-on {
  color: var(--ink);
  border-color: rgba(255, 208, 138, 0.25);
}

.auto-toggle.is-on .auto-dot {
  background: var(--gold);
  box-shadow: 0 0 9px 2px rgba(255, 208, 138, 0.6);
}

.perf-box {
  display: flex;
  align-items: center;
  height: 32px;
  padding: 0 12px;
  gap: 6px;
  border: 1px solid var(--line-soft);
  background: rgba(6, 9, 16, 0.38);
  backdrop-filter: blur(12px);
  border-radius: 999px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--dim);
}

.perf-box #fpsValue {
  color: rgba(255, 255, 255, 0.87);
  font-variant-numeric: tabular-nums;
  font-size: 10px;
}

.perf-box small {
  font-size: 7px;
  margin-left: -2px;
}

.perf-box i {
  width: 1px;
  height: 11px;
  background: var(--line);
  margin: 0 4px;
}

.perf-box .particles {
  color: rgba(255, 255, 255, 0.36);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------- mode rail ------------------------------- */
.mode-rail {
  position: absolute;
  top: calc(79px + var(--safe-top));
  left: calc(30px + var(--safe-left));
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  background: rgba(5, 8, 14, 0.35);
  backdrop-filter: blur(14px);
  z-index: 4;
  max-width: calc(100vw - 60px);
  overflow-x: auto;
  scrollbar-width: none;
  pointer-events: auto;
}

.mode-rail::-webkit-scrollbar {
  display: none;
}

.mode-btn {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 6px;
  height: 29px;
  padding: 0 11px;
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  transition: color 0.25s ease, background 0.25s ease;
}

.mode-btn span {
  color: rgba(255, 255, 255, 0.23);
  font-size: 7px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.mode-btn:hover {
  color: rgba(255, 255, 255, 0.78);
}

.mode-btn.is-active {
  color: #0b0c10;
  background: linear-gradient(135deg, #ffe1af, #ffc474);
  box-shadow: 0 2px 12px rgba(255, 180, 90, 0.17);
}

.mode-btn.is-active span {
  color: rgba(10, 10, 12, 0.45);
}

/* ------------------------------- show meta ------------------------------- */
.show-meta {
  position: absolute;
  left: calc(34px + var(--safe-left));
  top: 50%;
  transform: translateY(-52%);
  max-width: 360px;
  z-index: 2;
  pointer-events: none;
  opacity: 0.96;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 255, 255, 0.44);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--rose);
  box-shadow: 0 0 10px 2px rgba(255, 95, 143, 0.5);
  animation: live-pulse 2.2s ease-in-out infinite;
}

.eyebrow-sep {
  color: rgba(255, 255, 255, 0.2);
}

@keyframes live-pulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

.show-meta h1 {
  font-family: var(--display);
  font-size: clamp(48px, 5.4vw, 82px);
  font-weight: 400;
  line-height: 0.9;
  letter-spacing: 0.045em;
  margin: 12px 0 11px -3px;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.25);
}

.show-meta p {
  margin: 0;
  max-width: 290px;
  color: rgba(242, 242, 245, 0.56);
  font-size: 11px;
  line-height: 1.65;
  font-weight: 400;
  letter-spacing: 0.01em;
}

.meta-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  margin-top: 19px;
  color: rgba(255, 255, 255, 0.32);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.meta-line span + span::before {
  content: "";
  display: inline-block;
  width: 12px;
  height: 1px;
  background: rgba(255, 255, 255, 0.22);
  vertical-align: middle;
  margin-right: 14px;
}

.show-progress {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: rgba(255, 255, 255, 0.04);
  z-index: 5;
  pointer-events: none;
}

.show-progress span {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, rgba(255, 157, 86, 0.2), var(--gold), #fff2d8);
  box-shadow: 0 0 10px rgba(255, 206, 134, 0.5);
  transition: width 0.15s linear;
}

/* ------------------------------- right rail ------------------------------- */
.right-rail {
  position: absolute;
  right: calc(24px + var(--safe-right));
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 7px;
  z-index: 4;
}

.rail-btn {
  width: 44px;
  min-height: 54px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: 1px solid var(--line-soft);
  border-radius: 13px;
  background: rgba(6, 9, 16, 0.4);
  backdrop-filter: blur(12px);
  color: rgba(255, 255, 255, 0.53);
  transition: 0.22s ease;
}

.rail-btn svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.35;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.rail-btn span {
  font-size: 5.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.rail-btn:hover,
.rail-btn.is-active {
  color: var(--gold);
  border-color: rgba(255, 208, 138, 0.24);
  background: rgba(20, 18, 18, 0.62);
}

.rail-btn.is-recording {
  color: #ff7188;
  border-color: rgba(255, 90, 120, 0.4);
}

/* ------------------------------- bottom area ------------------------------- */
.bottom-area {
  position: absolute;
  left: 50%;
  bottom: calc(20px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  z-index: 6;
  width: min(92vw, 540px);
}

.quick-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 0 8px;
}

.quick-btn {
  height: 31px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 13px;
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  background: rgba(6, 9, 16, 0.42);
  backdrop-filter: blur(14px);
  color: rgba(255, 255, 255, 0.52);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.13em;
  transition: 0.22s ease;
}

.quick-btn:hover,
.quick-btn.is-active {
  color: var(--gold);
  border-color: rgba(255, 208, 138, 0.23);
}

.quick-btn .plus {
  color: var(--gold);
  font-size: 13px;
  line-height: 1;
  font-weight: 300;
}

.quick-btn b {
  color: var(--gold);
  font-weight: 800;
}

.quick-btn .timer-icon {
  font-size: 12px;
  color: rgba(255, 208, 138, 0.75);
}

.dock {
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 3px;
  width: 100%;
  padding: 5px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 22px;
  background: rgba(6, 9, 15, 0.7);
  backdrop-filter: blur(24px) saturate(130%);
  box-shadow:
    0 20px 65px rgba(0, 0, 0, 0.48),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
}

.dock-btn {
  flex: 1;
  min-width: 0;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 17px;
  color: rgba(255, 255, 255, 0.58);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  transition: 0.22s ease;
}

.dock-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.055);
}

.dock-btn--play {
  flex: 1.7;
  background: linear-gradient(135deg, #ffe4b2 0%, #ffc26f 50%, #ffa95c 100%);
  color: #12100c;
  box-shadow: 0 6px 24px rgba(255, 173, 83, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.dock-btn--play:hover {
  color: #12100c;
  background: linear-gradient(135deg, #ffedc8 0%, #ffce86 50%, #ffb66b 100%);
  box-shadow: 0 8px 30px rgba(255, 173, 83, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.dock-icon {
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
}

.dock-icon svg {
  width: 16px;
  height: 16px;
}

.dock-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dock-btn--play.is-paused .dock-icon svg {
  width: 15px;
}

.track-info {
  position: absolute;
  left: calc(32px + var(--safe-left));
  bottom: calc(28px + var(--safe-bottom));
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 3;
  color: rgba(255, 255, 255, 0.74);
  pointer-events: none;
}

.track-info > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.track-info span {
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.17em;
}

.track-info small {
  color: rgba(255, 255, 255, 0.27);
  font-size: 5.5px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.track-bars {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 15px;
}

.track-bars i {
  display: block;
  width: 2px;
  border-radius: 2px;
  background: rgba(255, 208, 138, 0.68);
  animation: meter 1.1s ease-in-out infinite alternate;
}

.track-bars i:nth-child(1) { height: 5px; animation-delay: -0.2s; }
.track-bars i:nth-child(2) { height: 12px; animation-delay: -0.65s; }
.track-bars i:nth-child(3) { height: 8px; animation-delay: -0.4s; }
.track-bars i:nth-child(4) { height: 4px; animation-delay: -0.9s; }

body.is-paused .track-bars i {
  animation-play-state: paused;
}

@keyframes meter {
  0% { transform: scaleY(0.42); opacity: 0.45; }
  100% { transform: scaleY(1); opacity: 1; }
}

.gesture-hint {
  position: absolute;
  left: 50%;
  bottom: calc(145px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 11px;
  color: rgba(255, 255, 255, 0.34);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
  white-space: nowrap;
  z-index: 3;
  transition: opacity 0.8s ease;
  pointer-events: none;
}

.gesture-hint.is-hidden {
  opacity: 0;
}

.gesture-hint i {
  width: 2px;
  height: 2px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 50%;
}

.hint-line {
  width: 26px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.26));
}

.hint-line:last-child {
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.26), transparent);
}

/* ------------------------------- state overlays ------------------------------- */
.slowmo-badge {
  position: absolute;
  left: 50%;
  top: calc(25px + var(--safe-top));
  transform: translate(-50%, -15px);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 15px;
  border: 1px solid rgba(255, 208, 138, 0.3);
  border-radius: 999px;
  background: rgba(8, 8, 12, 0.65);
  backdrop-filter: blur(14px);
  color: var(--gold);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.18em;
  z-index: 8;
  opacity: 0;
  visibility: hidden;
  transition: 0.3s ease;
  pointer-events: none;
}

.slowmo-badge b {
  color: rgba(255, 255, 255, 0.8);
  font-weight: 700;
}

.slowmo-badge span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 10px 2px rgba(255, 208, 138, 0.6);
  animation: live-pulse 1s ease infinite;
}

.slowmo-badge.is-visible {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

.toast {
  position: absolute;
  left: 50%;
  bottom: calc(230px + var(--safe-bottom));
  transform: translate(-50%, 12px);
  padding: 10px 16px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 999px;
  background: rgba(7, 10, 17, 0.84);
  backdrop-filter: blur(16px);
  color: rgba(255, 255, 255, 0.84);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  white-space: nowrap;
  z-index: 40;
  opacity: 0;
  visibility: hidden;
  transition: 0.3s ease;
  pointer-events: none;
}

.toast.is-visible {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

.rec-badge {
  position: absolute;
  top: calc(69px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(10, 8, 10, 0.7);
  border: 1px solid rgba(255, 80, 110, 0.26);
  color: rgba(255, 255, 255, 0.74);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.15em;
  z-index: 9;
  opacity: 0;
  visibility: hidden;
  transition: 0.25s ease;
  pointer-events: none;
}

.rec-badge.is-visible {
  opacity: 1;
  visibility: visible;
}

.rec-badge span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ff5a76;
  box-shadow: 0 0 10px 2px rgba(255, 80, 110, 0.65);
  animation: live-pulse 1.15s ease infinite;
}

.rec-badge b {
  color: #fff;
  font-variant-numeric: tabular-nums;
}

.cinema-bar {
  position: fixed;
  left: 0;
  right: 0;
  height: 0;
  background: #000;
  z-index: 8;
  pointer-events: none;
  transition: height 1.1s cubic-bezier(0.22, 1, 0.36, 1);
}

.cinema-bar--top { top: 0; }
.cinema-bar--bottom { bottom: 0; }

body.mode-cinematic .cinema-bar {
  height: 30px;
}

/* ------------------------------- photo mode ------------------------------- */
.photo-hud {
  position: absolute;
  inset: 0;
  display: none;
  z-index: 20;
  pointer-events: none;
}

body.photo-mode #ui > *:not(.photo-hud) {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

body.photo-mode .photo-hud {
  display: block;
}

.photo-title {
  position: absolute;
  top: calc(26px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255, 255, 255, 0.68);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.7);
}

.photo-title span {
  color: var(--gold);
  margin: 0 5px;
}

.photo-actions {
  position: absolute;
  bottom: calc(34px + var(--safe-bottom));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 22px;
  pointer-events: auto;
}

.shutter-btn {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.7);
  display: grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(10px);
  transition: 0.18s ease;
}

.shutter-btn span {
  width: 49px;
  height: 49px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  display: block;
  transition: 0.18s ease;
}

.shutter-btn:active span {
  transform: scale(0.9);
}

.photo-exit {
  height: 37px;
  padding: 0 18px;
  border: 1px solid rgba(255, 255, 255, 0.27);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(10px);
  color: rgba(255, 255, 255, 0.7);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.17em;
}

.photo-tip {
  position: absolute;
  bottom: calc(110px + var(--safe-bottom));
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255, 255, 255, 0.3);
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.17em;
  white-space: nowrap;
}

/* ------------------------------- sheet ------------------------------- */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 30;
  background: rgba(0, 0, 0, 0.48);
  backdrop-filter: blur(2px);
  opacity: 0;
  visibility: hidden;
  transition: 0.32s ease;
}

.sheet-backdrop.is-open {
  opacity: 1;
  visibility: visible;
}

.sheet {
  position: fixed;
  top: 12px;
  right: 12px;
  bottom: 12px;
  width: min(430px, calc(100vw - 24px));
  z-index: 31;
  display: flex;
  flex-direction: column;
  padding: 19px 20px calc(24px + var(--safe-bottom));
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 22px;
  background:
    linear-gradient(160deg, rgba(22, 21, 26, 0.86), rgba(7, 9, 15, 0.95) 38%),
    var(--panel-solid);
  backdrop-filter: blur(30px) saturate(130%);
  box-shadow: -20px 30px 80px rgba(0, 0, 0, 0.52);
  transform: translateX(calc(100% + 30px));
  visibility: hidden;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1), visibility 0.45s;
  overflow: hidden;
}

.sheet.is-open {
  transform: translateX(0);
  visibility: visible;
}

.sheet-grab {
  display: none;
}

.sheet-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex: 0 0 auto;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line-soft);
}

.sheet-head h2 {
  margin: 6px 0 0;
  font-family: var(--display);
  font-size: 30px;
  font-weight: 400;
  letter-spacing: 0.06em;
  line-height: 0.92;
}

.sheet-close {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: rgba(255, 255, 255, 0.55);
  font-size: 21px;
  font-weight: 300;
  line-height: 1;
  transition: 0.2s ease;
}

.sheet-close:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.32);
}

.panel {
  overflow-y: auto;
  overflow-x: hidden;
  padding: 3px 2px 10px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.18) transparent;
  overscroll-behavior: contain;
}

.panel::-webkit-scrollbar {
  width: 3px;
}

.panel::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.16);
  border-radius: 99px;
}

.panel[hidden] {
  display: none;
}

.panel-section {
  padding: 17px 0;
  border-bottom: 1px solid var(--line-soft);
}

.panel-section:last-child {
  border-bottom: 0;
}

.section-label {
  color: rgba(255, 255, 255, 0.45);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.muted {
  display: block;
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.31);
  font-size: 8.5px;
  line-height: 1.45;
}

.row-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.mini-badge,
.value-badge {
  flex: 0 0 auto;
  padding: 5px 8px;
  border-radius: 7px;
  background: rgba(255, 208, 138, 0.08);
  border: 1px solid rgba(255, 208, 138, 0.16);
  color: var(--gold);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.09em;
  font-variant-numeric: tabular-nums;
}

.view-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-top: 11px;
}

.view-btn {
  min-height: 92px;
  padding: 12px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.025);
  color: rgba(255, 255, 255, 0.48);
  transition: 0.22s ease;
}

.view-btn .view-glyph {
  font-size: 18px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.55);
}

.view-btn b {
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.view-btn small {
  color: rgba(255, 255, 255, 0.26);
  font-size: 6.5px;
}

.view-btn:hover,
.view-btn.is-active {
  border-color: rgba(255, 208, 138, 0.33);
  background: rgba(255, 208, 138, 0.065);
  color: var(--ink);
}

.view-btn.is-active .view-glyph {
  color: var(--gold);
  text-shadow: 0 0 14px rgba(255, 208, 138, 0.6);
}

.slider-row {
  margin-top: 17px;
}

.range {
  -webkit-appearance: none;
  appearance: none;
  width: 120px;
  height: 20px;
  background: transparent;
  cursor: pointer;
}

.range--wide {
  width: 100%;
  margin-top: 11px;
}

.range::-webkit-slider-runnable-track {
  height: 2px;
  border-radius: 99px;
  background: linear-gradient(90deg, rgba(255, 208, 138, 0.8), rgba(255, 255, 255, 0.15));
}

.range::-moz-range-track {
  height: 2px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.18);
}

.range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 12px;
  height: 12px;
  margin-top: -5px;
  border-radius: 50%;
  background: #fff1d8;
  border: 1px solid rgba(255, 208, 138, 0.8);
  box-shadow: 0 0 10px rgba(255, 208, 138, 0.4);
}

.range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff1d8;
  border: 1px solid rgba(255, 208, 138, 0.8);
}

.option-row {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.action-tile {
  flex: 1;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.025);
  color: rgba(255, 255, 255, 0.64);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.11em;
  transition: 0.2s ease;
}

.action-tile:hover {
  border-color: rgba(255, 255, 255, 0.28);
  color: #fff;
}

.action-tile--accent {
  border-color: rgba(255, 208, 138, 0.27);
  background: rgba(255, 208, 138, 0.07);
  color: var(--gold);
}

.panel-note {
  padding: 15px 1px 0;
  color: rgba(255, 255, 255, 0.26);
  font-size: 7.5px;
  line-height: 1.7;
}

.switch {
  position: relative;
  flex: 0 0 auto;
  width: 38px;
  height: 21px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
  transition: 0.22s ease;
}

.switch i {
  position: absolute;
  left: 3px;
  top: 3px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.4);
  transition: 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.switch.is-on {
  background: rgba(255, 208, 138, 0.2);
  border-color: rgba(255, 208, 138, 0.4);
}

.switch.is-on i {
  left: 20px;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(255, 208, 138, 0.5);
}

.segment {
  display: flex;
  gap: 3px;
  margin-top: 11px;
  padding: 3px;
  border: 1px solid var(--line-soft);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.16);
}

.segment button {
  flex: 1;
  height: 30px;
  border-radius: 7px;
  color: rgba(255, 255, 255, 0.34);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.08em;
  transition: 0.2s ease;
}

.segment button:hover {
  color: rgba(255, 255, 255, 0.72);
}

.segment button.is-active {
  background: rgba(255, 208, 138, 0.13);
  color: var(--gold);
  box-shadow: inset 0 0 0 1px rgba(255, 208, 138, 0.16);
}

.segment--small {
  width: 122px;
  flex: 0 0 auto;
  margin-top: 0;
}

.toggles {
  padding-top: 6px;
  padding-bottom: 6px;
}

.toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  cursor: pointer;
}

.toggle-row span {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.toggle-row b {
  font-size: 8.5px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.72);
}

.toggle-row small {
  color: rgba(255, 255, 255, 0.26);
  font-size: 7px;
}

.toggle-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-top: 13px;
}

.chip-toggle {
  height: 34px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
  color: rgba(255, 255, 255, 0.3);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.07em;
  transition: 0.2s ease;
}

.chip-toggle.is-on {
  border-color: rgba(255, 208, 138, 0.22);
  background: rgba(255, 208, 138, 0.06);
  color: var(--gold);
}

.telemetry {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}

.telemetry div {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.telemetry span {
  color: rgba(255, 255, 255, 0.24);
  font-size: 5.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.telemetry b {
  color: rgba(255, 255, 255, 0.73);
  font-size: 10px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

/* custom show */
.shape-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 5px;
  margin-top: 11px;
}

.shape-btn {
  min-width: 0;
  height: 57px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.018);
  color: rgba(255, 255, 255, 0.46);
  transition: 0.2s ease;
}

.shape-btn span {
  font-size: 16px;
  line-height: 1;
}

.shape-btn b {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 5.2px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.shape-btn:hover,
.shape-btn.is-active {
  border-color: rgba(255, 208, 138, 0.33);
  background: rgba(255, 208, 138, 0.06);
  color: var(--gold);
}

.color-custom {
  position: relative;
  width: 28px;
  height: 28px;
  border: 1px solid var(--line);
  border-radius: 50%;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.7);
  font-size: 14px;
  cursor: pointer;
}

.color-custom input {
  position: absolute;
  inset: -8px;
  width: 44px;
  height: 44px;
  opacity: 0;
  cursor: pointer;
}

.palette {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 12px;
}

.swatch {
  position: relative;
  width: 29px;
  height: 29px;
  border-radius: 50%;
  background: var(--swatch);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.23), 0 0 16px color-mix(in srgb, var(--swatch) 32%, transparent);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.swatch:hover {
  transform: translateY(-2px);
}

.swatch.is-active::after {
  content: "";
  position: absolute;
  inset: -4px;
  border: 1px solid var(--swatch);
  border-radius: 50%;
  box-shadow: 0 0 12px color-mix(in srgb, var(--swatch) 45%, transparent);
}

.sequence-section {
  min-height: 100px;
}

.count-badge {
  display: inline-grid;
  place-items: center;
  min-width: 17px;
  height: 17px;
  margin-left: 5px;
  padding: 0 4px;
  border-radius: 99px;
  background: rgba(255, 208, 138, 0.12);
  color: var(--gold);
  font-size: 6px;
}

.text-btn {
  color: rgba(255, 255, 255, 0.3);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.text-btn:hover {
  color: var(--rose);
}

.sequence-list {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 11px;
}

.sequence-empty {
  width: 100%;
  padding: 18px 10px;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.26);
  font-size: 7.5px;
  line-height: 1.55;
  text-align: center;
}

.seq-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 27px;
  padding: 0 8px 0 6px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.025);
  color: rgba(255, 255, 255, 0.5);
  font-size: 6.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.seq-chip i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--chip-color);
  box-shadow: 0 0 7px var(--chip-color);
}

.seq-chip button {
  margin-left: 1px;
  color: rgba(255, 255, 255, 0.24);
  font-size: 12px;
  line-height: 1;
}

.seq-chip button:hover {
  color: var(--rose);
}

.wide-cta {
  width: 100%;
  height: 47px;
  border-radius: 12px;
  background: linear-gradient(135deg, #ffe4b2, #ffc26f 55%, #ffa95c);
  color: #17120b;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.15em;
  box-shadow: 0 9px 30px rgba(255, 173, 83, 0.16);
  transition: 0.2s ease;
}

.wide-cta span {
  margin-right: 6px;
  font-size: 11px;
}

.wide-cta:disabled {
  opacity: 0.24;
  pointer-events: none;
}

.wide-cta:not(:disabled):hover {
  filter: brightness(1.07);
}

/* ------------------------------- responsive ------------------------------- */
@media (max-width: 900px) {
  .show-meta {
    max-width: 300px;
  }

  .show-meta h1 {
    font-size: clamp(42px, 8vw, 68px);
  }

  .track-info {
    display: none;
  }
}

@media (max-width: 680px) {
  .topbar {
    padding: calc(13px + var(--safe-top)) calc(14px + var(--safe-right)) 0 calc(15px + var(--safe-left));
  }

  .brand {
    gap: 9px;
  }

  .brand-mark {
    width: 32px;
    height: 32px;
  }

  .brand-mark svg {
    width: 19px;
    height: 19px;
  }

  .brand-name {
    font-size: 17px;
  }

  .brand-tag {
    font-size: 5.5px;
    letter-spacing: 0.16em;
  }

  .top-actions {
    gap: 6px;
  }

  .auto-toggle {
    height: 28px;
    padding: 0 9px;
    font-size: 6.5px;
  }

  .perf-box {
    height: 28px;
    padding: 0 8px;
    font-size: 6px;
    gap: 4px;
  }

  .perf-box .particles {
    display: none;
  }

  .perf-box i {
    margin: 0 2px;
  }

  .mode-rail {
    top: calc(55px + var(--safe-top));
    left: calc(12px + var(--safe-left));
    max-width: calc(100vw - 24px);
    padding: 3px;
  }

  .mode-btn {
    height: 27px;
    padding: 0 9px;
    font-size: 6.5px;
    gap: 4px;
  }

  .mode-btn span {
    display: none;
  }

  .show-meta {
    top: auto;
    bottom: calc(145px + var(--safe-bottom));
    left: calc(18px + var(--safe-left));
    transform: none;
    max-width: 260px;
  }

  .show-meta h1 {
    font-size: clamp(32px, 11vw, 46px);
    margin: 7px 0 6px;
  }

  .show-meta p {
    display: none;
  }

  .eyebrow {
    font-size: 6.5px;
    letter-spacing: 0.17em;
  }

  .meta-line {
    margin-top: 8px;
    font-size: 5.5px;
    gap: 9px;
    letter-spacing: 0.12em;
  }

  .meta-line span + span::before {
    width: 7px;
    margin-right: 9px;
  }

  .right-rail {
    right: calc(9px + var(--safe-right));
    top: 46%;
    gap: 5px;
  }

  .rail-btn {
    width: 39px;
    min-height: 45px;
    border-radius: 11px;
    gap: 2px;
  }

  .rail-btn svg {
    width: 16px;
    height: 16px;
  }

  .rail-btn span {
    font-size: 4.5px;
  }

  .bottom-area {
    bottom: calc(9px + var(--safe-bottom));
    width: calc(100vw - 18px);
    gap: 7px;
  }

  .quick-row {
    padding: 0 4px;
  }

  .quick-btn {
    height: 28px;
    padding: 0 10px;
    font-size: 6.2px;
    letter-spacing: 0.09em;
  }

  .quick-btn b {
    display: none;
  }

  .dock {
    border-radius: 19px;
    padding: 4px;
  }

  .dock-btn {
    height: 45px;
    border-radius: 14px;
    font-size: 6.5px;
    gap: 5px;
    letter-spacing: 0.06em;
  }

  .dock-btn--play {
    flex: 1.55;
  }

  .dock-icon svg {
    width: 14px;
    height: 14px;
  }

  .gesture-hint {
    display: none;
  }

  .toast {
    bottom: calc(180px + var(--safe-bottom));
    max-width: 92vw;
    white-space: normal;
    text-align: center;
    font-size: 7px;
  }

  .slowmo-badge {
    top: calc(96px + var(--safe-top));
    font-size: 6px;
    padding: 7px 11px;
  }

  .rec-badge {
    top: calc(96px + var(--safe-top));
  }

  .cinema-bar {
    display: none;
  }

  .sheet {
    top: auto;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    max-height: 86dvh;
    padding: 14px 15px calc(18px + var(--safe-bottom));
    border-radius: 23px 23px 0 0;
    border-bottom: 0;
    transform: translateY(calc(100% + 20px));
  }

  .sheet.is-open {
    transform: translateY(0);
  }

  .sheet-grab {
    display: block;
    width: 35px;
    height: 3px;
    border-radius: 99px;
    background: rgba(255, 255, 255, 0.17);
    margin: -2px auto 13px;
    flex: 0 0 auto;
  }

  .sheet-head h2 {
    font-size: 26px;
  }

  .sheet-head {
    padding-bottom: 12px;
