521:       second.clone().offsetHSL(-0.08, 0.06, 0.02),
522:       base.clone(),
523:     ];
524:     const tmpColor = new THREE.Color();
525:     const endColor = new THREE.Color();
526:     const dir = new THREE.Vector3();
527:     const randomSphere = () => {
528:       const z = Math.random() * 2 - 1;
529:       const phi = Math.random() * TAU;
530:       const r = Math.sqrt(Math.max(0, 1 - z * z));
531:       dir.set(Math.cos(phi) * r, z, Math.sin(phi) * r);
532:       return dir;
533:     };
534: 
535:     for (let i = 0; i < count; i++) {
536:       let layer = 0;
537:       let layerSpeed = 1;
538:       let layerSize = 1;
539:       let pattern = this.type;
540: 
541:       if (this.type === 'multi' || this.type === 'mega') {
542:         const roll = Math.random();
543:         layer = roll < 0.42 ? 0 : roll < 0.78 ? 1 : 2;
544:         layerSpeed = [0.54, 0.78, 1][layer] * rand(0.93, 1.07);
545:         layerSize = [0.78, 0.92, 1.12][layer];
546:         layerMeta[i] = layer;
547:       }
548: 
549:       if (this.type === 'heart') {
550:         const point = samplePolyline(HEART_POINTS);
551:         const fill = Math.random() < 0.17 ? Math.pow(Math.random(), 0.32) * 0.72 : 1;
552:         dir
553:           .copy(basis.right)
554:           .multiplyScalar(point[0] * fill)
555:           .addScaledVector(basis.up, point[1] * fill)
556:           .addScaledVector(basis.normal, gauss() * 0.055);
557:         if (dir.lengthSq() < 0.0001) dir.copy(basis.up);
558:         dir.normalize();
559:       } else if (this.type === 'star') {
560:         const point = samplePolyline(STAR_POINTS);
561:         const fill = Math.random() < 0.12 ? Math.pow(Math.random(), 0.3) * 0.65 : 1;
562:         dir
563:           .copy(basis.right)
564:           .multiplyScalar(point[0] * fill)
565:           .addScaledVector(basis.up, point[1] * fill)
566:           .addScaledVector(basis.normal, gauss() * 0.045);
567:         if (dir.lengthSq() < 0.0001) dir.copy(basis.up);
568:         dir.normalize();
569:       } else if (this.type === 'ring') {
570:         const angle = Math.random() * TAU;
571:         const tilt = rand(-0.18, 0.18);
572:         const cos = Math.cos(angle);
573:         const sin = Math.sin(angle);
574:         dir
575:           .copy(basis.right)
576:           .multiplyScalar(cos)
577:           .addScaledVector(basis.up, sin)
