584:       } else {
585:         dir.copy(randomSphere());
586:       }
587: 
588:       const radial = 0.88 + Math.random() * 0.24;
589:       const shapeSpeed =
590:         this.type === 'heart' || this.type === 'star' || this.type === 'ring'
591:           ? cfg.speed * scale * rand(0.94, 1.04)
592:           : cfg.speed * scale * radial * layerSpeed;
593:       const speed = shapeSpeed * (this.type === 'mega' ? 1.18 : 1);
594: 
595:       const p = center;
596:       const startJitter = this.type === 'willow' ? 1.9 : 1.2;
597:       positions[i * 3] = p.x + gauss() * startJitter * scale;
598:       positions[i * 3 + 1] = p.y + gauss() * startJitter * scale;
599:       positions[i * 3 + 2] = p.z + gauss() * startJitter * scale;
600: 
601:       velocities[i * 3] = dir.x * speed;
602:       velocities[i * 3 + 1] = dir.y * speed;
603:       velocities[i * 3 + 2] = dir.z * speed;
604: 
605:       // Colour design. Rainbow gets a full hue sweep around the shell.
606:       if (this.type === 'rainbow') {
607:         const az = Math.atan2(dir.z, dir.x) / TAU + 0.5;
608:         const hue = (az + dir.y * 0.1 + 1) % 1;
609:         tmpColor.setHSL(hue, 0.96, 0.62);
610:         endColor.setHSL((hue + 0.22) % 1, 0.95, 0.53);
611:       } else if (this.type === 'glitter') {
612:         if (Math.random() < 0.55) tmpColor.setHSL(0.1 + Math.random() * 0.04, 0.56, 0.72);
613:         else tmpColor.copy(base).offsetHSL(rand(-0.04, 0.04), 0, rand(-0.08, 0.18));
614:         endColor.copy(tmpColor).offsetHSL(0.04, 0, -0.1);
615:       } else if (this.type === 'multi' || this.type === 'mega') {
616:         tmpColor.copy(multiPalette[layer]).offsetHSL(rand(-0.025, 0.025), rand(-0.05, 0.07), rand(-0.05, 0.08));
617:         endColor.copy(tmpColor).offsetHSL(layer === 0 ? -0.12 : 0.11, 0, -0.1);
618:       } else if (this.type === 'willow') {
619:         tmpColor.setHSL(0.09 + Math.random() * 0.045, 0.9, 0.6 + Math.random() * 0.12);
620:         endColor.setHSL(0.055, 0.92, 0.34);
621:       } else {
622:         tmpColor.copy(base).offsetHSL(rand(-0.035, 0.035), rand(-0.03, 0.05), rand(-0.08, 0.1));
623:         endColor.copy(tmpColor).offsetHSL(rand(-0.1, 0.14), 0.03, -0.12);
624:       }
625: 
626:       const brightness =
627:         (this.type === 'glitter' ? rand(1.8, 3.2) : rand(1.85, 2.85)) *
628:         (this.type === 'multi' || this.type === 'mega' ? [1.15, 1, 0.9][layer] : 1);
629:       starts[i * 3] = tmpColor.r * brightness;
630:       starts[i * 3 + 1] = tmpColor.g * brightness;
631:       starts[i * 3 + 2] = tmpColor.b * brightness;
632:       ends[i * 3] = endColor.r * rand(0.55, 1.05);
633:       ends[i * 3 + 1] = endColor.g * rand(0.55, 1.05);
634:       ends[i * 3 + 2] = endColor.b * rand(0.55, 1.05);
635: 
636:       const l = cfg.life[0] + Math.random() * (cfg.life[1] - cfg.life[0]);
637:       const layerLife = this.type === 'multi' || this.type === 'mega' ? [1.12, 1, 0.86][layer] : 1;
638:       life[i] = l * layerLife;
639:       maxLife[i] = life[i];
640:       drags[i] = cfg.drag * rand(0.92, 1.08);
641:       gravities[i] = cfg.gravity * rand(0.82, 1.16);
642:       baseSizes[i] = (cfg.size[0] + Math.random() * (cfg.size[1] - cfg.size[0])) * scale * layerSize;
643:       sizes[i] = baseSizes[i];
644:       phases[i] = Math.random() * TAU;
645:       twinkles[i] = cfg.twinkle * rand(0.55, 1.2);
646:       swirls[i] = rand(-0.9, 0.9);
647:       trailScales[i] = cfg.trail * this.system.trailMultiplier * rand(0.75, 1.25) * this.scale;
648:     }
649: 
650:     const geo = new THREE.BufferGeometry();
651:     geo.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
652:     geo.setAttribute('aColor', new THREE.BufferAttribute(colors, 3).setUsage(THREE.DynamicDrawUsage));
653:     geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1).setUsage(THREE.DynamicDrawUsage));
654: 
655:     const points = new THREE.Points(geo, this.system.particleMaterial);
