660:     const trailGeo = new THREE.BufferGeometry();
661:     trailGeo.setAttribute('position', new THREE.BufferAttribute(trailPositions, 3).setUsage(THREE.DynamicDrawUsage));
662:     trailGeo.setAttribute('color', new THREE.BufferAttribute(trailColors, 3).setUsage(THREE.DynamicDrawUsage));
663:     const trails = new THREE.LineSegments(trailGeo, this.system.trailMaterial);
664:     trails.frustumCulled = false;
665:     trails.renderOrder = 11;
666:     this.scene.add(trails);
