668:     this.particles = {
669:       points,
670:       trails,
671:       geometry: geo,
672:       trailGeometry: trailGeo,
673:       count,
674:       positions,
675:       colors,
676:       sizes,
677:       velocities,
678:       starts,
679:       ends,
680:       life,
681:       maxLife,
682:       drags,
683:       gravities,
684:       baseSizes,
685:       phases,
686:       twinkles,
687:       swirls,
688:       trailScales,
689:       trailPositions,
