696:   updateParticles(dt, time) {
697:     const p = this.particles;
698:     if (!p) return;
699:     const pos = p.positions;
700:     const vel = p.velocities;
701:     const colors = p.colors;
702:     const sizes = p.sizes;
703:     const trailPos = p.trailPositions;
704:     const trailCol = p.trailColors;
705:     let alive = 0;
706: 
707:     for (let i = 0; i < p.count; i++) {
708:       if (p.life[i] <= 0) {
709:         colors[i * 3] = 0;
710:         colors[i * 3 + 1] = 0;
711:         colors[i * 3 + 2] = 0;
712:         sizes[i] = 0;
713:         continue;
714:       }
715: 
716:       alive++;
717:       p.life[i] -= dt;
718:       const age = p.maxLife[i] - p.life[i];
719:       const dragFactor = Math.exp(-p.drags[i] * dt);
720:       vel[i * 3] *= dragFactor;
721:       vel[i * 3 + 1] *= dragFactor;
722:       vel[i * 3 + 2] *= dragFactor;
723:       vel[i * 3 + 1] -= p.gravities[i] * dt;
724: 
725:       // A tiny curl force makes long sparks arc naturally instead of falling in straight lines.
726:       const swirl = p.swirls[i];
727:       vel[i * 3] += Math.sin(time * 0.55 + p.phases[i]) * swirl * dt * 0.26;
728:       vel[i * 3 + 2] += Math.cos(time * 0.62 + p.phases[i] * 1.3) * swirl * dt * 0.22;
729: 
730:       pos[i * 3] += vel[i * 3] * dt;
731:       pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
732:       pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
733: 
734:       const remaining = p.life[i];
735:       const lifeRatio = clamp(remaining / p.maxLife[i], 0, 1);
736:       const fadeIn = clamp(age / 0.075, 0, 1);
737:       const fadeOut = clamp(remaining / (p.maxLife[i] * 0.42), 0, 1);
738:       const fade = fadeIn * Math.min(1, fadeOut * 1.55) * (0.9 + lifeRatio * 0.1);
739:       const mixT = clamp(age / (p.maxLife[i] * 0.78), 0, 1);
740: 
741:       let flicker = 1;
742:       if (p.twinkles[i] > 0.001) {
743:         const tw = 0.5 + 0.5 * Math.sin(time * 11.5 + p.phases[i]);
744:         flicker = 1 - p.twinkles[i] * 0.62 * Math.pow(tw, 5);
745:       }
746: 
747:       const r = (p.starts[i * 3] + (p.ends[i * 3] - p.starts[i * 3]) * mixT) * fade * flicker;
748:       const g = (p.starts[i * 3 + 1] + (p.ends[i * 3 + 1] - p.starts[i * 3 + 1]) * mixT) * fade * flicker;
749:       const b = (p.starts[i * 3 + 2] + (p.ends[i * 3 + 2] - p.starts[i * 3 + 2]) * mixT) * fade * flicker;
750:       colors[i * 3] = r;
751:       colors[i * 3 + 1] = g;
752:       colors[i * 3 + 2] = b;
753: 
754:       const sizePulse = 0.72 + 0.28 * fadeIn;
755:       sizes[i] = p.baseSizes[i] * sizePulse * (0.62 + 0.38 * lifeRatio);
756: 
757:       const trailScale = p.trailScales[i] * (0.45 + 0.55 * fadeOut);
758:       const vx = vel[i * 3] * trailScale;
759:       const vy = vel[i * 3 + 1] * trailScale;
760:       const vz = vel[i * 3 + 2] * trailScale;
761:       const px = pos[i * 3];
762:       const py = pos[i * 3 + 1];
763:       const pz = pos[i * 3 + 2];
764: 
765:       const t0 = i * 12;
766:       // Segment 1: head to mid, segment 2: mid to tail.
767:       trailPos[t0] = px;
768:       trailPos[t0 + 1] = py;
769:       trailPos[t0 + 2] = pz;
770:       trailPos[t0 + 3] = px - vx * 0.38;
771:       trailPos[t0 + 4] = py - vy * 0.38;
772:       trailPos[t0 + 5] = pz - vz * 0.38;
773:       trailPos[t0 + 6] = px - vx * 0.38;
774:       trailPos[t0 + 7] = py - vy * 0.38;
775:       trailPos[t0 + 8] = pz - vz * 0.38;
776:       trailPos[t0 + 9] = px - vx;
777:       trailPos[t0 + 10] = py - vy;
778:       trailPos[t0 + 11] = pz - vz;
779: 
780:       trailCol[t0] = r * 0.8;
781:       trailCol[t0 + 1] = g * 0.8;
782:       trailCol[t0 + 2] = b * 0.8;
783:       trailCol[t0 + 3] = r * 0.42;
784:       trailCol[t0 + 4] = g * 0.42;
785:       trailCol[t0 + 5] = b * 0.42;
786:       trailCol[t0 + 6] = r * 0.42;
787:       trailCol[t0 + 7] = g * 0.42;
788:       trailCol[t0 + 8] = b * 0.42;
789:       trailCol[t0 + 9] = r * 0.09;
790:       trailCol[t0 + 10] = g * 0.09;
791:       trailCol[t0 + 11] = b * 0.09;
792:     }
793: 
794:     p.geometry.attributes.position.needsUpdate = true;
795:     p.geometry.attributes.aColor.needsUpdate = true;
796:     p.geometry.attributes.aSize.needsUpdate = true;
797:     p.trailGeometry.attributes.position.needsUpdate = true;
798:     p.trailGeometry.attributes.color.needsUpdate = true;
799:     this.liveParticleCount = alive;
800: 
801:     if (alive === 0) {
802:       this.removeParticles();
803:     }
804:   }
