944:   updateEffects(dt) {
945:     for (let i = this.effects.length - 1; i >= 0; i--) {
946:       const fx = this.effects[i];
947:       fx.t += dt;
948:       if (fx.t < 0) continue;
949:       const progress = clamp(fx.t / fx.life, 0, 1);
950:       const sprite = fx.sprite;
951:       if (fx.type === 'smoke') {
952:         sprite.position.addScaledVector(fx.velocity, dt);
953:         fx.velocity.y += dt * 0.16;
954:         fx.velocity.multiplyScalar(Math.exp(-0.06 * dt));
955:         const scale = THREE.MathUtils.lerp(fx.start, fx.end, Math.pow(progress, 0.55));
956:         sprite.scale.set(scale, scale * 0.8, 1);
957:         sprite.material.opacity = fx.baseOpacity * Math.sin(Math.PI * progress) * (1 - progress * 0.2);
958:         if (fx.rotate) sprite.material.rotation += fx.rotationSpeed * dt;
959:       } else {
960:         const ease = fx.type === 'flash' ? Math.pow(progress, 0.28) : 1 - Math.pow(1 - progress, 2.4);
961:         const scale = THREE.MathUtils.lerp(fx.start, fx.end, ease);
962:         sprite.scale.setScalar(scale);
