addWaterReflection() {
  const world = this.system.world;
  if (!world?.glowTex || !world.reflectionEnabled) return;
  const camera = this.system.camera;
  const eye = Math.max(1, camera.position.y);
  const t = eye / (eye + Math.max(1, this.explosionCenter.y));
  const x = camera.position.x + (this.explosionCenter.x - camera.position.x) * t;
  const z = camera.position.z + (this.explosionCenter.z - camera.position.z) * t;
  const cfg = this.cfg;
  const width = (30 + cfg.flash * 16) * this.scale;
  const depth = (110 + cfg.flash * 75) * this.scale;
  const mat = new THREE.MeshBasicMaterial({
    map: world.glowTex,
    color: this.color,
    transparent: true,
    opacity: 0.2,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
    side: THREE.DoubleSide,
  });
  const geo = new THREE.PlaneGeometry(1, 1);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(x, 0.12, z);
  mesh.renderOrder = 6;
  this.scene.add(mesh);
  this.effects.push({
    type: 'water',
    sprite: mesh,
    geometry: geo,
    t: 0,
    life: 1.5 + cfg.flash * 0.22,
    width,
    depth,
    baseOpacity: 0.2,
    rotate: false,
  });
}

